export type ThemeName = "superapp";

export const themeNames: ThemeName[] = ["superapp"];

export type KcEnvName = "SUPERAPP_GOOGLE_LOGIN_ENABLED";

export const kcEnvNames: KcEnvName[] = ["SUPERAPP_GOOGLE_LOGIN_ENABLED"];

